import { useEffect, useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import neuralNetworkGif from '@assets/Artificial Intelligence Nft GIF by xponentialdesign_1763654069407.gif';

type JarvisState = 'IDLE' | 'LISTENING' | 'PROCESSING' | 'SPEAKING';

interface Event {
  timestamp: string;
  message: string;
}

interface SystemMetrics {
  cpu: number;
  ram: number;
  sensitivity: number;
}

const STATE_COLORS = {
  IDLE: {
    hex: '#00f0ff',
    rgb: 'rgb(0, 240, 255)',
    label: 'STANDBY'
  },
  LISTENING: {
    hex: '#0080ff',
    rgb: 'rgb(0, 128, 255)',
    label: 'RECEIVING INPUT'
  },
  PROCESSING: {
    hex: '#ffaa00',
    rgb: 'rgb(255, 170, 0)',
    label: 'ANALYZING'
  },
  SPEAKING: {
    hex: '#00ff88',
    rgb: 'rgb(0, 255, 136)',
    label: 'RESPONDING'
  }
};

export default function JarvisHUD() {
  const [status, setStatus] = useState<JarvisState>('IDLE');
  const [events, setEvents] = useState<Event[]>([]);
  const [systemMetrics, setSystemMetrics] = useState<SystemMetrics>({
    cpu: 23,
    ram: 41,
    sensitivity: 75
  });
  const [brainStatus, setBrainStatus] = useState({
    connected: true,
    model: 'GPT-4o',
    latency: 127
  });

  const wsRef = useRef<WebSocket | null>(null);
  const eventLogRef = useRef<HTMLDivElement>(null);

  const addEvent = (message: string) => {
    const now = new Date();
    const timestamp = now.toLocaleTimeString('en-US', { hour12: false });
    setEvents(prev => [...prev.slice(-99), { timestamp, message }]);
  };

  useEffect(() => {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}/jarvis-ws`;

    const connectWebSocket = () => {
      const ws = new WebSocket(wsUrl);
      wsRef.current = ws;

      ws.onopen = () => {
        console.log('Connected to Jarvis WebSocket');
        addEvent('SYSTEM >> WebSocket connection established');
      };

      ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);

          switch (data.type) {
            case 'updateCoreState':
              const newState = data.state?.toUpperCase();
              if (newState && newState in STATE_COLORS) {
                setStatus(newState as JarvisState);
                addEvent(`CORE >> State changed to ${newState}`);
              }
              break;
            case 'updateBrainStatus':
              if (data.isOnline !== undefined) {
                setBrainStatus(prev => ({ ...prev, connected: data.isOnline }));
              }
              if (data.modelName) {
                setBrainStatus(prev => ({ ...prev, model: data.modelName }));
              }
              break;
            case 'addEventLog':
              if (data.message) {
                addEvent(`EVENT >> ${data.message}`);
              }
              break;
          }
        } catch (error) {
          console.error('WebSocket message parse error:', error);
        }
      };

      ws.onerror = (error) => {
        console.error('WebSocket error:', error);
      };

      ws.onclose = () => {
        console.log('WebSocket disconnected, reconnecting in 3s...');
        setTimeout(connectWebSocket, 3000);
      };
    };

    connectWebSocket();

    return () => {
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, []);

  useEffect(() => {
    if (eventLogRef.current) {
      eventLogRef.current.scrollTop = eventLogRef.current.scrollHeight;
    }
  }, [events]);

  useEffect(() => {
    const interval = setInterval(() => {
      setSystemMetrics({
        cpu: Math.floor(15 + Math.random() * 20),
        ram: Math.floor(35 + Math.random() * 15),
        sensitivity: 70 + Math.floor(Math.random() * 15)
      });
      setBrainStatus(prev => ({
        ...prev,
        latency: Math.floor(80 + Math.random() * 100)
      }));
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    addEvent('JARVIS >> System initialization complete');
    addEvent('NEURAL >> All systems nominal');
    addEvent('READY >> Awaiting commands...');
  }, []);

  useEffect(() => {
    const stateCycleDemo = setInterval(() => {
      setStatus(prev => {
        const states: JarvisState[] = ['IDLE', 'LISTENING', 'PROCESSING', 'SPEAKING'];
        const currentIndex = states.indexOf(prev);
        const nextIndex = (currentIndex + 1) % states.length;
        const nextState = states[nextIndex];
        console.log(`State cycling: ${prev} -> ${nextState}`);
        return nextState;
      });
    }, 4000);

    console.log('State cycle interval started');
    return () => {
      console.log('State cycle interval cleared');
      clearInterval(stateCycleDemo);
    };
  }, []);

  const currentColor = STATE_COLORS[status];

  return (
    <div className="h-screen w-screen bg-background overflow-hidden flex flex-col">
      <div className="flex-1 grid grid-cols-1 lg:grid-cols-[minmax(280px,1fr)_2fr_minmax(280px,1fr)] gap-4 p-4">
        <SystemHealthPanel metrics={systemMetrics} />

        <div className="flex flex-col items-center justify-center">
          <PulsingOrb status={status} color={currentColor.rgb} />
          <motion.div
            className="mt-8 text-center"
            key={status}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
          >
            <p 
              className="text-4xl font-bold tracking-widest font-['Orbitron']"
              style={{ color: currentColor.hex, textShadow: `0 0 20px ${currentColor.rgb}` }}
              data-testid="text-status-main"
            >
              {status}
            </p>
            <p 
              className="text-sm text-muted-foreground mt-2 tracking-wider font-['Rajdhani']"
              data-testid="text-status-label"
            >
              {currentColor.label}
            </p>
          </motion.div>
        </div>

        <BrainStatusPanel brainStatus={brainStatus} />
      </div>

      <EventLogTerminal events={events} eventLogRef={eventLogRef} />
    </div>
  );
}

function PulsingOrb({ status, color }: { status: JarvisState; color: string }) {
  const getFilterForState = (state: JarvisState) => {
    switch (state) {
      case 'IDLE':
        return 'hue-rotate(180deg) saturate(1.5) brightness(1.2)';
      case 'LISTENING':
        return 'hue-rotate(210deg) saturate(1.3) brightness(1.1)';
      case 'PROCESSING':
        return 'hue-rotate(40deg) saturate(1.8) brightness(1.3)';
      case 'SPEAKING':
        return 'hue-rotate(140deg) saturate(1.5) brightness(1.2)';
      default:
        return 'none';
    }
  };

  return (
    <div className="relative">
      <motion.div
        className="w-[500px] h-[500px] relative flex items-center justify-center"
        animate={{
          scale: [1, 1.05, 1],
          opacity: [0.9, 1, 0.9]
        }}
        transition={{
          duration: 2.5,
          repeat: Infinity,
          ease: "easeInOut"
        }}
      >
        <motion.div
          className="absolute inset-0 rounded-full"
          style={{
            background: `radial-gradient(circle at center, ${color}22 0%, transparent 70%)`,
            boxShadow: `0 0 80px ${color}88, 0 0 120px ${color}55, 0 0 160px ${color}33`,
            filter: 'blur(20px)'
          }}
          animate={{
            scale: [1, 1.2, 1],
          }}
          transition={{
            duration: 3,
            repeat: Infinity,
            ease: "easeInOut"
          }}
        />

        <motion.img
          src={neuralNetworkGif}
          alt="Neural Network Visualization"
          className="relative z-10 w-full h-full object-contain"
          style={{
            filter: getFilterForState(status),
            mixBlendMode: 'screen',
            transition: 'filter 0.5s ease-in-out'
          }}
          animate={{
            scale: [1, 1.02, 1],
          }}
          transition={{
            duration: 2.5,
            repeat: Infinity,
            ease: "easeInOut"
          }}
        />

        <motion.div
          className="absolute inset-0 rounded-full border border-primary/20"
          animate={{
            scale: [1, 1.15, 1],
            opacity: [0.3, 0.6, 0.3]
          }}
          transition={{
            duration: 2.5,
            repeat: Infinity,
            ease: "easeInOut",
            delay: 0.3
          }}
        />
      </motion.div>
    </div>
  );
}

function SystemHealthPanel({ metrics }: { metrics: SystemMetrics }) {
  return (
    <motion.div
      className="glass-panel rounded-lg p-6 h-full flex flex-col"
      initial={{ opacity: 0, x: -20 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ duration: 0.6 }}
      data-testid="panel-system-health"
    >
      <h2 className="text-xl font-bold text-primary mb-6 tracking-widest uppercase font-['Orbitron']">
        System Health
      </h2>

      <div className="flex-1 space-y-6">
        <MetricDisplay label="CPU USAGE" value={metrics.cpu} unit="%" max={100} />
        <MetricDisplay label="RAM USAGE" value={metrics.ram} unit="%" max={100} />
        <MetricDisplay label="SENSITIVITY" value={metrics.sensitivity} unit="%" max={100} />
      </div>

      <div className="mt-6 pt-4 border-t border-primary/20">
        <div className="flex justify-between items-center text-xs">
          <span className="text-muted-foreground font-['Roboto_Mono']">UPTIME</span>
          <span className="text-foreground font-['Roboto_Mono']">14:23:47</span>
        </div>
      </div>
    </motion.div>
  );
}

function MetricDisplay({ label, value, unit, max }: { label: string; value: number; unit: string; max: number }) {
  const percentage = (value / max) * 100;

  return (
    <div data-testid={`metric-${label.toLowerCase().replace(' ', '-')}`}>
      <div className="flex justify-between items-center mb-2">
